def compute(vars):
    base_value = vars["v1"]
    current_value = vars["v2"]

    if base_value == 0:
        return None

    change = current_value - base_value
    percentage_change = (change / base_value) * 100

    return {
        "value": percentage_change,
        "trace": {
            "base_value": base_value,
            "current_value": current_value,
            "change": change,
            "output_meta": {
                "currency": "USD",
                "scale": "millions",
                "unit": "percent"
            }
        }
    }
